def tri(tab):
    echanges = 0
    for i in range(1, len(tab)):
        for j in range(len(tab)-i):
            if tab[j] > tab[j+1]:
                tab[j], tab[j+1] = tab[j+1], tab[j]
                echanges += 1
    return echanges

# Pire cas : tableau trié en ordre décroissant
pire = list(range(10, 0, -1))
