import time
def search(x, y):
    for i in range(len(y)):
        if x == y[i]: return i
    return None

for n in [1000, 10000, 100000]:
    y = list(range(n))
    t = time.time()
    search(n-1, y)  # pire cas
    print(f'n={n}: {(time.time()-t)*1e6:.1f}µs')
